    "path": ".github/workflows/build-ipa.yml",
    "language": "yaml",
    "description": "GitHub Actions macOS 14 CI/CD workflow: runs npm test, generates Xcode project, and builds unsigned & signed .ipa",
    "content": "name: Build iOS IPA & Run Unit Tests\n\non:\n  push:\n    branches: [ \"main\" ]\n    tags: [ \"v*\" ]\n  pull_request:\n    branches: [ \"main\" ]\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  build-ios:\n    name: Build Unsigned & Signed iOS IPA (macOS 14 / Xcode 15.4)\n    runs-on: macos-14\n\n    steps:\n      - name: Checkout Repository\n        uses: actions/checkout@v4\n\n      - name: Setup Node.js 22\n        uses: actions/setup-node@v4\n        with:\n          node-version: \"22\"\n          cache: \"npm\"\n\n      - name: Install Dependencies & Run Automated Unit Tests\n        run: |\n          npm install\n          npm test\n\n      - name: Generate Xcode Project via XcodeGen\n        working-directory: ios\n        run: |\n          if ! command -v xcodegen &> /dev/null; then\n            brew install xcodegen\n          fi\n          xcodegen generate\n\n      - name: Build Unsigned Release App & Package Unsigned IPA (AltStore / Sideloadly / TrollStore)\n        working-directory: ios\n        run: |\n          xcodebuild clean build \\\n            -project iOS-ZTPreBlackoutNotification.xcodeproj \\\n            -scheme ZTPreBlackout \\\n            -configuration Release \\\n            -sdk iphoneos \\\n            -derivedDataPath build/DerivedData \\\n            CODE_SIGN_IDENTITY=\"\" \\\n            CODE_SIGNING_REQUIRED=NO \\\n            CODE_SIGNING_ALLOWED=NO\n\n          mkdir -p build/UnsignedIPA/Payload\n          cp -R build/DerivedData/Build/Products/Release-iphoneos/ZTPreBlackout.app build/UnsignedIPA/Payload/\n          cd build/UnsignedIPA\n          zip -qry ../iOS-ZTPreBlackoutNotification-unsigned.ipa Payload\n\n      - name: Optional Apple Developer Certificate Signing (TestFlight / App Store)\n        if: ${{ secrets.BUILD_CERTIFICATE_BASE64 != '' && secrets.BUILD_PROVISION_PROFILE_BASE64 != '' }}\n        working-directory: ios\n        env:\n          BUILD_CERTIFICATE_BASE64: ${{ secrets.BUILD_CERTIFICATE_BASE64 }}\n          P12_PASSWORD: ${{ secrets.P12_PASSWORD }}\n          BUILD_PROVISION_PROFILE_BASE64: ${{ secrets.BUILD_PROVISION_PROFILE_BASE64 }}\n          KEYCHAIN_PASSWORD: ${{ secrets.KEYCHAIN_PASSWORD }}\n        run: |\n          CERTIFICATE_PATH=$RUNNER_TEMP/build_certificate.p12\n          PP_PATH=$RUNNER_TEMP/build_pp.mobileprovision\n          KEYCHAIN_PATH=$RUNNER_TEMP/app-signing.keychain-db\n\n          echo -n \"$BUILD_CERTIFICATE_BASE64\" | base64 --decode -o $CERTIFICATE_PATH\n          echo -n \"$BUILD_PROVISION_PROFILE_BASE64\" | base64 --decode -o $PP_PATH\n\n          security create-keychain -p \"$KEYCHAIN_PASSWORD\" $KEYCHAIN_PATH\n          security set-keychain-settings -lut 21600 $KEYCHAIN_PATH\n          security unlock-keychain -p \"$KEYCHAIN_PASSWORD\" $KEYCHAIN_PATH\n          security import $CERTIFICATE_PATH -P \"$P12_PASSWORD\" -A -t cert -f pkcs12 -k $KEYCHAIN_PATH\n          security list-keychain -d user -s $KEYCHAIN_PATH\n\n          mkdir -p ~/Library/MobileDevice/Provisioning\\ Profiles\n          cp $PP_PATH ~/Library/MobileDevice/Provisioning\\ Profiles\n\n      - name: Upload Unsigned IPA Artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: iOS-ZTPreBlackoutNotification-unsigned-ipa\n          path: ios/build/iOS-ZTPreBlackoutNotification-unsigned.ipa\n          if-no-files-found: error\n\n      - name: Publish GitHub Release on Tag Push (v*)\n        if: startsWith(github.ref, 'refs/tags/v')\n        uses: softprops/action-gh-release@v2\n        with:\n          files: |\n            ios/build/iOS-ZTPreBlackoutNotification-unsigned.ipa\n          generate_release_notes: true\n"
